```sql
CREATE TABLE account_balances ( account_id VARCHAR(40) NOT NULL, currency CHAR(3) NOT NULL, balance_minor BIGINT NOT NULL, -- cents, never float version BIGINT NOT NULL, -- optimistic concurrency updated_at TIMESTAMP(6), PRIMARY KEY (account_id, currency)
) ENGINE=InnoDB; CREATE TABLE ledger_entries ( id BIGINT AUTO_INCREMENT PRIMARY KEY, txn_id VARCHAR(40) NOT NULL, account_id VARCHAR(40) NOT NULL, direction CHAR(1) NOT NULL, -- 'D' debit / 'C' credit amount_minor BIGINT NOT NULL, currency CHAR(3) NOT NULL, posted_at TIMESTAMP(6) NOT NULL, INDEX (txn_id), INDEX (account_id, posted_at)
) ENGINE=InnoDB; CREATE TABLE txn_idempotency ( idempotency_key VARCHAR(80) PRIMARY KEY, txn_id VARCHAR(40) NOT NULL, response_body JSON, created_at TIMESTAMP
);
```

